// Receipt reducer: reduce a JSONL run log into a per-job attempt report.
// Node.js builtins only. See task.md for the contract.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import process from 'node:process';

const TYPES = new Set(['started', 'succeeded', 'failed']);
const REQUIRED = ['id', 'job', 'attempt', 'seq', 'type'];

function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function validate(raw, lineNo) {
  if (!isPlainObject(raw)) throw new Error(`line ${lineNo}: event must be a JSON object`);
  const { id, job, attempt, seq, type } = raw;
  if (typeof id !== 'string' || id.length === 0) throw new Error(`line ${lineNo}: "id" must be a nonempty string`);
  if (typeof job !== 'string' || job.length === 0) throw new Error(`line ${lineNo}: "job" must be a nonempty string`);
  if (typeof attempt !== 'number' || !Number.isSafeInteger(attempt) || attempt < 1) {
    throw new Error(`line ${lineNo}: "attempt" must be a positive safe integer`);
  }
  if (typeof seq !== 'number' || !Number.isSafeInteger(seq) || seq < 0) {
    throw new Error(`line ${lineNo}: "seq" must be a nonnegative safe integer`);
  }
  if (typeof type !== 'string' || !TYPES.has(type)) {
    throw new Error(`line ${lineNo}: "type" must be one of started, succeeded, failed`);
  }
  return { id, job, attempt, seq, type };
}

function sameEvent(a, b) {
  return REQUIRED.every(k => a[k] === b[k]);
}

export function reduceEvents(text) {
  if (typeof text !== 'string') throw new Error('input must be a string');
  const byId = new Map();
  let duplicates = 0;
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === '') continue;
    let raw;
    try {
      raw = JSON.parse(line);
    } catch (err) {
      throw new Error(`line ${i + 1}: invalid JSON (${err.message})`);
    }
    const ev = validate(raw, i + 1);
    const prev = byId.get(ev.id);
    if (prev === undefined) {
      byId.set(ev.id, ev);
    } else if (sameEvent(prev, ev)) {
      duplicates++;
    } else {
      throw new Error(`line ${i + 1}: conflicting event for id ${JSON.stringify(ev.id)}`);
    }
  }

  // job -> Map(attempt -> {start, terminal})
  const jobs = new Map();
  for (const ev of byId.values()) {
    let attempts = jobs.get(ev.job);
    if (!attempts) { attempts = new Map(); jobs.set(ev.job, attempts); }
    let rec = attempts.get(ev.attempt);
    if (!rec) { rec = { start: null, terminal: null }; attempts.set(ev.attempt, rec); }
    const where = `job ${JSON.stringify(ev.job)} attempt ${ev.attempt}`;
    if (ev.type === 'started') {
      if (rec.start) throw new Error(`${where}: repeated started event (ids ${JSON.stringify(rec.start.id)}, ${JSON.stringify(ev.id)})`);
      rec.start = ev;
    } else {
      if (rec.terminal) {
        const kind = rec.terminal.type === ev.type ? 'repeated' : 'contradictory';
        throw new Error(`${where}: ${kind} terminal events (ids ${JSON.stringify(rec.terminal.id)}, ${JSON.stringify(ev.id)})`);
      }
      rec.terminal = ev;
    }
  }

  const out = [];
  for (const job of [...jobs.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const attempts = jobs.get(job);
    const list = [];
    for (const attempt of [...attempts.keys()].sort((a, b) => a - b)) {
      const { start, terminal } = attempts.get(attempt);
      const where = `job ${JSON.stringify(job)} attempt ${attempt}`;
      if (!start) throw new Error(`${where}: terminal event ${JSON.stringify(terminal.id)} without a started event`);
      if (terminal && terminal.seq <= start.seq) {
        throw new Error(`${where}: terminal seq ${terminal.seq} is not greater than started seq ${start.seq}`);
      }
      list.push({
        attempt,
        status: terminal ? terminal.type : 'running',
        startedSeq: start.seq,
        finishedSeq: terminal ? terminal.seq : null,
      });
    }
    out.push({ job, attempts: list });
  }
  return { jobs: out, duplicates };
}

export function main(argv = process.argv.slice(2)) {
  if (argv.length !== 1) {
    process.stderr.write('usage: node receipt-report.js LOGFILE\n');
    return 2;
  }
  let report;
  try {
    const text = readFileSync(argv[0], 'utf8');
    report = reduceEvents(text);
  } catch (err) {
    process.stderr.write(`receipt-report: ${err && err.message ? err.message : String(err)}\n`);
    return 2;
  }
  process.stdout.write(JSON.stringify(report) + '\n');
  return 0;
}

const isCli = (() => {
  try {
    return process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1];
  } catch {
    return false;
  }
})();
if (isCli) process.exitCode = main();
EOF
