  assert.equal(r.duplicates, 2);
  assert.deepEqual(r.jobs[0].attempts.map(a => a.attempt), [1, 2, 10]);
  assert.deepEqual(r.jobs[0].attempts[1], { attempt: 2, status: 'failed', startedSeq: 1, finishedSeq: 3 });
